    code: {
      "Default": "import { FormSection } from \"@design-systems-orion/blocks/form-section\";\nimport { Button, Input } from \"@design-systems-orion/ui\";\nimport { FormField } from \"@design-systems-orion/blocks/form-field\";\n\nconst Campos = () => (\n\t<>\n\t\t<FormField label=\"Nome\" htmlFor=\"fs-nome\">\n\t\t\t<Input id=\"fs-nome\" />\n\t\t</FormField>\n\t\t<FormField label=\"Código\" htmlFor=\"fs-cod\">\n\t\t\t<Input id=\"fs-cod\" />\n\t\t</FormField>\n\t</>\n);\n\nexport function FormSectionDemo() {\n\treturn (\n\t\t<FormSection title=\"Dados gerais\" className=\"w-96\">\n\t\t\t<Campos />\n\t\t</FormSection>\n\t);\n}",
      "WithDescription": "import { FormSection } from \"@design-systems-orion/blocks/form-section\";\nimport { Button, Input } from \"@design-systems-orion/ui\";\nimport { FormField } from \"@design-systems-orion/blocks/form-field\";\n\nconst Campos = () => (\n\t<>\n\t\t<FormField label=\"Nome\" htmlFor=\"fs-nome\">\n\t\t\t<Input id=\"fs-nome\" />\n\t\t</FormField>\n\t\t<FormField label=\"Código\" htmlFor=\"fs-cod\">\n\t\t\t<Input id=\"fs-cod\" />\n\t\t</FormField>\n\t</>\n);\n\nexport function FormSectionWithDescription() {\n\treturn (\n\t\t<FormSection\n\t\t\ttitle=\"Dados gerais\"\n\t\t\tdescription=\"Informações principais do registro.\"\n\t\t\tclassName=\"w-96\"\n\t\t>\n\t\t\t<Campos />\n\t\t</FormSection>\n\t);\n}",
      "WithActions": "import { FormSection } from \"@design-systems-orion/blocks/form-section\";\nimport { Button, Input } from \"@design-systems-orion/ui\";\nimport { FormField } from \"@design-systems-orion/blocks/form-field\";\n\nconst Campos = () => (\n\t<>\n\t\t<FormField label=\"Nome\" htmlFor=\"fs-nome\">\n\t\t\t<Input id=\"fs-nome\" />\n\t\t</FormField>\n\t\t<FormField label=\"Código\" htmlFor=\"fs-cod\">\n\t\t\t<Input id=\"fs-cod\" />\n\t\t</FormField>\n\t</>\n);\n\nexport function FormSectionWithActions() {\n\treturn (\n\t\t<FormSection\n\t\t\ttitle=\"Endereços\"\n\t\t\tactions={\n\t\t\t\t<Button variant=\"outline\" size=\"sm\">\n\t\t\t\t\tAdicionar\n\t\t\t\t</Button>\n\t\t\t}\n\t\t\tclassName=\"w-96\"\n\t\t>\n\t\t\t<Campos />\n\t\t</FormSection>\n\t);\n}",
      "MultipleSections": "import { FormSection } from \"@design-systems-orion/blocks/form-section\";\nimport { Button, Input } from \"@design-systems-orion/ui\";\nimport { FormField } from \"@design-systems-orion/blocks/form-field\";\n\nconst Campos = () => (\n\t<>\n\t\t<FormField label=\"Nome\" htmlFor=\"fs-nome\">\n\t\t\t<Input id=\"fs-nome\" />\n\t\t</FormField>\n\t\t<FormField label=\"Código\" htmlFor=\"fs-cod\">\n\t\t\t<Input id=\"fs-cod\" />\n\t\t</FormField>\n\t</>\n);\n\nexport function FormSectionMultipleSections() {\n\treturn (\n\t\t<div className=\"w-96 space-y-8\">\n\t\t\t<FormSection title=\"Dados gerais\">\n\t\t\t\t<Campos />\n\t\t\t</FormSection>\n\t\t\t<FormSection title=\"Configurações\" description=\"Ajustes opcionais.\">\n\t\t\t\t<Campos />\n\t\t\t</FormSection>\n\t\t</div>\n\t);\n}",
    },
